# -*- coding: utf-8 -*-
import os
import sys
import base64
import subprocess

print("=====================================================================")
print("      UOR-R4 ECOSYSTEM SECURE REPOSITORY BUILDER & INITIALIZER       ")
print("=====================================================================")

project_dir = "uor-r4-project"

if os.path.exists(project_dir):
    print(f"Error: Directory '{project_dir}' already exists. Aborting to protect existing files.")
    sys.exit(1)

os.makedirs(project_dir)
print(f"Created workspace directory '{project_dir}/'")

# Embedded file database (base64 encoded to prevent unicode escaping issues)
file_db = {
    r'index.html': '',
    r'Cargo.toml': '',
    r'.github/workflows/deploy.yml': '',
    r'tests/cordic_conformance_kani.rs': '',
    r'tests/uor_wasm_bridge_kani.rs': '',
    r'tests/uor_compressor_kani.rs': '',
    r'tests/uor_chatbot_recursion_kani.rs': '',
    r'tests/unicode_lexical_parser_kani.rs': '',
    r'src/geometric_attention.rs': '',
    r'src/hopf_angular_routing.rs': '',
    r'src/vsa_binding.rs': '',
    r'src/unicode_lexical_parser.rs': '',
    r'src/lib.rs': '',
    r'src/bin/uor_workspace_orchestrator.rs': '',
    r'src/bin/uor_codebook_loader.rs': '',
    r'src/bin/uor_chatbot.rs': '',
    r'src/bin/uor_terminal_dashboard.rs': '',
    r'src/bin/uor_codebook_compressor.rs': '',
}

# Recreate files
for path, b64_data in file_db.items():
    full_dest = os.path.join(project_dir, path)
    os.makedirs(os.path.dirname(full_dest), exist_ok=True)
    with open(full_dest, "wb") as f:
        f.write(base64.b64decode(b64_data.encode('utf-8')))
    print(f"  ├─ Recreated {path}")

print("---------------------------------------------------------------------")

# Write custom README.md
readme_content = """# UOR-R4 High-Performance WASM Generative AI & Verification Workspace

This repository unifies the complete **UOR-R4 cognitive routing substrate** into an interactive WebAssembly-powered browser interface, complete with in-browser alignment training and Kani formal verification suites.

## Project Layout

*   `.github/workflows/deploy.yml`: Automated GitHub Actions deployment to GitHub Pages.
*   `index.html`: Standalone browser dashboard containing local-first chat REPL and local SGD alignment.
*   `src/lib.rs`: WebAssembly wrapper module exposing client-side APIs.
*   `tests/`: Bounded model checking files (Kani) verifying absolute memory and integer overflow safety.
*   `src/bin/`: Standalone optimized utilities (Generative chatbot REPL, parallel E8 database compression and mmap loader, ANSI metrics dashboard).

## Compiling WebAssembly Locally

```bash
# Compile and package WASM bridge
wasm-pack build --target web --release
```

## Running Verification

```bash
# Run Kani verification proofs
cargo kani --file tests/unicode_lexical_parser_kani.rs
```
"""

with open(os.path.join(project_dir, "README.md"), "w") as f:
    f.write(readme_content)
print("  ├─ Recreated README.md")

print("---------------------------------------------------------------------")
print("Initiating local Git repository configuration...")

try:
    # 1. git init
    subprocess.run(["git", "init", "-b", "main"], cwd=project_dir, check=True)
    
    # 2. Configure default bot identity (required for committing inside sandbox / environments)
    subprocess.run(["git", "config", "user.name", "UOR Foundation Bot"], cwd=project_dir, check=True)
    subprocess.run(["git", "config", "user.email", "bot@uor.foundation"], cwd=project_dir, check=True)
    
    # 3. git add
    subprocess.run(["git", "add", "."], cwd=project_dir, check=True)
    
    # 4. git commit
    subprocess.run(["git", "commit", "-m", "Initial commit of UOR-R4 Unified WASM Chat & Verification Ecosystem"], cwd=project_dir, check=True)
    
    print("\n🎉 SUCCESS! Fully compiled local Git repository created successfully.")
    print(f"Your workspace is ready in the folder: '{project_dir}'")
    print("=====================================================================")
except Exception as e:
    print(f"\nWarning: Git repository initialization failed: {e}")
    print(f"Directory '{project_dir}' was successfully created with all source files.")
    print("=====================================================================")
